-- Repaired form-template seed: 20260710054300_reseed_growth_form_templates.
-- The original 2026-01 seed contained malformed JSON delimiters and is now a
-- safe historical marker. This idempotent seed preserves the intended forms.

with seed as (
  select
    (item->>'module')::public.module_type as module,
    item->>'name' as name,
    item->>'description' as description,
    item->'schema_json' as schema_json,
    coalesce((item->>'is_active')::boolean, true) as is_active
  from jsonb_array_elements($hpg_forms$[{"module":"development","name":"Grant research update","description":"Document grant opportunity research findings","schema_json":{"fields":[{"name":"funder_name","type":"text","label":"Funder Name","required":true},{"name":"opportunity_name","type":"text","label":"Opportunity/Program Name","required":true},{"name":"amount_range","type":"text","label":"Award Amount Range"},{"name":"deadline","type":"date","label":"Application Deadline"},{"name":"fit_score","type":"select","label":"Fit Score","options":["Low","Medium","High"]},{"name":"research_notes","type":"textarea","label":"Research Notes","required":true}]},"is_active":true},{"module":"development","name":"Opportunity qualification","description":"Qualify a grant opportunity for pursuit","schema_json":{"fields":[{"name":"opportunity_name","type":"text","label":"Opportunity Name","required":true},{"name":"funder_name","type":"text","label":"Funder Name","required":true},{"name":"qualification_score","type":"select","label":"Qualification Score","options":["Low","Medium","High"],"required":true},{"name":"strategic_fit","type":"textarea","label":"Strategic Fit Assessment","required":true},{"name":"resource_requirements","type":"textarea","label":"Resource Requirements"},{"name":"recommendation","type":"select","label":"Recommendation","options":["Pursue","Decline","Defer"],"required":true}]},"is_active":true},{"module":"development","name":"LOI/proposal submission packet","description":"Submit letter of intent or grant proposal for review","schema_json":{"fields":[{"name":"opportunity_name","type":"text","label":"Opportunity Name","required":true},{"name":"submission_type","type":"select","label":"Submission Type","options":["Letter of Intent","Full Proposal","Concept Paper"],"required":true},{"name":"deadline","type":"date","label":"Submission Deadline","required":true},{"name":"requested_amount","type":"number","label":"Requested Amount ($)"},{"name":"project_summary","type":"textarea","label":"Project Summary","required":true},{"name":"attachments_uploaded","type":"checkbox","label":"All Required Attachments Uploaded"}]},"is_active":true},{"module":"development","name":"Post-award reporting submission","description":"Submit required post-award reports","schema_json":{"fields":[{"name":"grant_name","type":"text","label":"Grant Name","required":true},{"name":"report_type","type":"select","label":"Report Type","options":["Progress Report","Financial Report","Final Report","Other"],"required":true},{"name":"reporting_period","type":"text","label":"Reporting Period","required":true},{"name":"due_date","type":"date","label":"Due Date","required":true},{"name":"activities_summary","type":"textarea","label":"Activities Summary","required":true},{"name":"budget_status","type":"textarea","label":"Budget Status"}]},"is_active":true},{"module":"partnership","name":"Partnership intake","description":"Intake form for new partnership opportunities","schema_json":{"fields":[{"name":"partner_name","type":"text","label":"Partner Organization Name","required":true},{"name":"partner_type","type":"select","label":"Partner Type","options":["Corporate","Foundation","Government","NGO","Academic","Other"],"required":true},{"name":"contact_name","type":"text","label":"Primary Contact Name","required":true},{"name":"contact_email","type":"email","label":"Contact Email","required":true},{"name":"partnership_scope","type":"textarea","label":"Partnership Scope","required":true},{"name":"potential_value","type":"textarea","label":"Potential Value"}]},"is_active":true},{"module":"partnership","name":"Meeting notes/follow-up","description":"Document partnership meeting notes and follow-up actions","schema_json":{"fields":[{"name":"partner_name","type":"text","label":"Partner Name","required":true},{"name":"meeting_date","type":"date","label":"Meeting Date","required":true},{"name":"attendees","type":"textarea","label":"Attendees","required":true},{"name":"meeting_summary","type":"textarea","label":"Meeting Summary","required":true},{"name":"key_decisions","type":"textarea","label":"Key Decisions"},{"name":"action_items","type":"textarea","label":"Action Items","required":true},{"name":"next_steps","type":"textarea","label":"Next Steps"}]},"is_active":true},{"module":"partnership","name":"MOU/contract request","description":"Request creation or review of MOU or partnership contract","schema_json":{"fields":[{"name":"partner_name","type":"text","label":"Partner Name","required":true},{"name":"document_type","type":"select","label":"Document Type","options":["MOU","Partnership Agreement","Contract","Other"],"required":true},{"name":"purpose","type":"textarea","label":"Purpose","required":true},{"name":"key_terms","type":"textarea","label":"Key Terms"},{"name":"urgency","type":"select","label":"Urgency","options":["Low","Medium","High"],"required":true},{"name":"legal_review_required","type":"checkbox","label":"Legal Review Required"}]},"is_active":true},{"module":"marketing","name":"Marketing request intake","description":"Request marketing support for campaigns or assets","schema_json":{"fields":[{"name":"request_type","type":"select","label":"Request Type","options":["Flyer/Poster","Social Media","Email Campaign","Website Update","Video","Other"],"required":true},{"name":"description","type":"textarea","label":"Description","required":true},{"name":"target_audience","type":"text","label":"Target Audience"},{"name":"due_date","type":"date","label":"Needed By"},{"name":"brand_guidelines","type":"checkbox","label":"Follow HPG brand guidelines"}]},"is_active":true},{"module":"marketing","name":"Asset request","description":"Request marketing assets or materials","schema_json":{"fields":[{"name":"asset_type","type":"select","label":"Asset Type","options":["Logo","Brand Guidelines","Templates","Photos","Videos","Other"],"required":true},{"name":"purpose","type":"textarea","label":"Purpose","required":true},{"name":"format_required","type":"text","label":"Format Required"},{"name":"due_date","type":"date","label":"Needed By"},{"name":"usage_rights","type":"select","label":"Usage Rights","options":["Internal Only","External","Public"]}]},"is_active":true},{"module":"marketing","name":"Monthly marketing report","description":"Submit monthly marketing activities and metrics report","schema_json":{"fields":[{"name":"reporting_period","type":"date","label":"Reporting Period","required":true},{"name":"campaigns_launched","type":"textarea","label":"Campaigns Launched","required":true},{"name":"metrics","type":"textarea","label":"Key Metrics"},{"name":"challenges","type":"textarea","label":"Challenges"},{"name":"next_month_plans","type":"textarea","label":"Next Month Plans","required":true}]},"is_active":true},{"module":"communications","name":"Press release request","description":"Request creation and distribution of a press release","schema_json":{"fields":[{"name":"title","type":"text","label":"Press Release Title","required":true},{"name":"event_date","type":"date","label":"Event/Announcement Date"},{"name":"key_points","type":"textarea","label":"Key Points","required":true},{"name":"target_media","type":"textarea","label":"Target Media Outlets"},{"name":"distribution_date","type":"date","label":"Desired Distribution Date"},{"name":"approvals_obtained","type":"checkbox","label":"All Approvals Obtained"}]},"is_active":true},{"module":"communications","name":"Newsletter issue builder","description":"Build content for newsletter issue","schema_json":{"fields":[{"name":"issue_date","type":"date","label":"Issue Date","required":true},{"name":"theme","type":"text","label":"Theme/Topic"},{"name":"featured_stories","type":"textarea","label":"Featured Stories","required":true},{"name":"upcoming_events","type":"textarea","label":"Upcoming Events"},{"name":"call_to_action","type":"textarea","label":"Call to Action"}]},"is_active":true},{"module":"communications","name":"Internal memo request","description":"Request creation and distribution of internal memo","schema_json":{"fields":[{"name":"subject","type":"text","label":"Subject","required":true},{"name":"recipients","type":"select","label":"Recipients","options":["All Staff","Management","Department Specific","Other"],"required":true},{"name":"content","type":"textarea","label":"Memo Content","required":true},{"name":"priority","type":"select","label":"Priority","options":["Normal","Urgent"]},{"name":"distribution_date","type":"date","label":"Distribution Date"}]},"is_active":true}]$hpg_forms$::jsonb) as seeded(item)
)
insert into public.form_templates (module, name, description, schema_json, is_active)
select module, name, description, schema_json, is_active
from seed
on conflict (module, name) do update set
  description = excluded.description,
  schema_json = excluded.schema_json,
  is_active = excluded.is_active,
  updated_at = now();
